publicsynchronizedvoidinsert(Objecto)
throwsInterruptedException
{
while(numOccupied==buffer.length)
//waitforspace
wait();
buffer[(firstOccupied+numOccupied)%buffer.length]=o;
numOccupied++;
//incaseanyretrievesarewaitingfordata,wakethem
notifyAll();
}
publicsynchronizedObjectretrieve()
throwsInterruptedException
{
while(numOccupied==0)
//waitfordata
wait();
Objectretrieved=buffer[firstOccupied];
buffer[firstOccupied]=null;//mayhelpgarbagecollector
firstOccupied=(firstOccupied+1)%buffer.length;
numOccupied--;
//incaseanyinsertsarewaitingforspace,wakethem
notifyAll();
returnretrieved;
}
}
